#include "../../framework/unity.h"
#include "../../../kernel/net_tls_record.h"
void setUp(void){} void tearDown(void){}
void test_tls_handshake_state(void){uint8_t hello[42]={0};net_tls_handshake_t handshake;hello[0]=2;hello[3]=38;hello[4]=3;hello[5]=3;for(uint8_t i=0;i<32;i++)hello[6+i]=i;hello[38]=0;hello[39]=0;hello[40]=0x9c;hello[41]=0;TEST_ASSERT_EQUAL(0,net_tls_handshake_init(&handshake));TEST_ASSERT_EQUAL(NET_TLS_HANDSHAKE_IDLE,handshake.state);TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_accept_server_hello(&handshake,hello,sizeof(hello)));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_client_hello(&handshake));TEST_ASSERT_EQUAL(NET_TLS_HANDSHAKE_CLIENT_HELLO_SENT,handshake.state);TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_hello(&handshake,hello,sizeof(hello)));TEST_ASSERT_EQUAL(NET_TLS_HANDSHAKE_SERVER_HELLO_RECEIVED,handshake.state);TEST_ASSERT_EQUAL(0x009c,handshake.cipher_suite);TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_accept_server_hello(&handshake,hello,sizeof(hello)));}
void test_tls_server_hello_parse(void){uint8_t hello[44]={0};net_tls_server_hello_view_t view;hello[0]=2;hello[3]=38;hello[4]=3;hello[5]=3;for(uint8_t i=0;i<32;i++)hello[6+i]=i;hello[38]=0;hello[39]=0;hello[40]=0x9c;hello[41]=0;TEST_ASSERT_EQUAL(0,net_tls_server_hello_parse(hello,42,&view));TEST_ASSERT_EQUAL(0x009c,view.cipher_suite);TEST_ASSERT_EQUAL(0,view.compression_method);hello[42]=0;hello[43]=0;hello[3]=40;TEST_ASSERT_EQUAL(0,net_tls_server_hello_parse(hello,44,&view));TEST_ASSERT_EQUAL(0,view.extensions_length);hello[43]=1;TEST_ASSERT_NOT_EQUAL(0,net_tls_server_hello_parse(hello,44,&view));hello[3]=38;hello[5]=1;TEST_ASSERT_NOT_EQUAL(0,net_tls_server_hello_parse(hello,42,&view));hello[5]=3;hello[41]=1;TEST_ASSERT_NOT_EQUAL(0,net_tls_server_hello_parse(hello,42,&view));}
void test_tls_certificate_parse(void){uint8_t message[18]={11,0,0,14,0,0,11,0,0,3,'A','B','C',0,0,2,'D','E'};net_tls_certificate_view_t view;TEST_ASSERT_EQUAL(0,net_tls_certificate_parse(message,sizeof(message),&view));TEST_ASSERT_EQUAL(11,view.certificate_list_length);TEST_ASSERT_EQUAL(3,view.certificate_length);TEST_ASSERT_EQUAL('A',view.certificate[0]);message[6]=12;TEST_ASSERT_NOT_EQUAL(0,net_tls_certificate_parse(message,sizeof(message),&view));message[6]=11;message[9]=0;TEST_ASSERT_NOT_EQUAL(0,net_tls_certificate_parse(message,sizeof(message),&view));}
void test_tls_certificate_handshake_state(void){uint8_t hello[42]={0},certificate[13]={11,0,0,9,0,0,6,0,0,3,'X','Y','Z'};net_tls_handshake_t handshake;hello[0]=2;hello[3]=38;hello[4]=3;hello[5]=3;hello[38]=0;hello[39]=0;hello[40]=0x9c;hello[41]=0;TEST_ASSERT_EQUAL(0,net_tls_handshake_init(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_client_hello(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_hello(&handshake,hello,sizeof(hello)));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_certificate(&handshake,certificate,sizeof(certificate)));TEST_ASSERT_EQUAL(NET_TLS_HANDSHAKE_CERTIFICATE_RECEIVED,handshake.state);TEST_ASSERT_EQUAL(3,handshake.server_certificate_length);TEST_ASSERT_EQUAL('X',handshake.server_certificate[0]);TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_accept_certificate(&handshake,certificate,sizeof(certificate)));}
void test_tls_server_hello_done(void){uint8_t done[4]={14,0,0,0};TEST_ASSERT_EQUAL(0,net_tls_server_hello_done_parse(done,sizeof(done)));done[3]=1;TEST_ASSERT_NOT_EQUAL(0,net_tls_server_hello_done_parse(done,sizeof(done)));done[3]=0;done[0]=13;TEST_ASSERT_NOT_EQUAL(0,net_tls_server_hello_done_parse(done,sizeof(done)));TEST_ASSERT_NOT_EQUAL(0,net_tls_server_hello_done_parse(done,3));}
void test_tls_server_hello_done_state(void){uint8_t hello[42]={0},certificate[13]={11,0,0,9,0,0,6,0,0,3,'X','Y','Z'},done[4]={14,0,0,0};net_tls_handshake_t handshake;hello[0]=2;hello[3]=38;hello[4]=3;hello[5]=3;hello[38]=0;hello[39]=0;hello[40]=0x9c;hello[41]=0;TEST_ASSERT_EQUAL(0,net_tls_handshake_init(&handshake));TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_accept_server_hello_done(&handshake,done,sizeof(done)));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_client_hello(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_hello(&handshake,hello,sizeof(hello)));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_certificate(&handshake,certificate,sizeof(certificate)));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_hello_done(&handshake,done,sizeof(done)));TEST_ASSERT_EQUAL(NET_TLS_HANDSHAKE_SERVER_HELLO_DONE_RECEIVED,handshake.state);TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_accept_server_hello_done(&handshake,done,sizeof(done)));}
void test_tls_handshake_fragment_and_transcript(void){uint8_t done[4]={14,0,0,0},assembly[8]={0},transcript_buffer[8]={0};net_tls_handshake_accumulator_t accumulator;net_tls_handshake_view_t view;net_tls_transcript_t transcript;TEST_ASSERT_EQUAL(0,net_tls_handshake_accumulator_init(&accumulator,assembly,sizeof(assembly)));TEST_ASSERT_EQUAL(1,net_tls_handshake_accumulator_feed(&accumulator,done,2,&view));TEST_ASSERT_EQUAL(0,net_tls_handshake_accumulator_feed(&accumulator,done+2,2,&view));TEST_ASSERT_EQUAL(14,view.type);TEST_ASSERT_EQUAL(0,view.body_length);TEST_ASSERT_EQUAL(0,net_tls_transcript_init(&transcript,transcript_buffer,sizeof(transcript_buffer)));TEST_ASSERT_EQUAL(0,net_tls_transcript_append(&transcript,done,sizeof(done)));TEST_ASSERT_EQUAL(4,transcript.length);TEST_ASSERT_NOT_EQUAL(0,net_tls_transcript_append(&transcript,(uint8_t[]){14,0,0,5},4));TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_accumulator_feed(&accumulator,done,1,&view));}
void test_tls_server_key_exchange_and_certificate_request(void){uint8_t exchange[17]={12,0,0,13,3,0,23,3,4,5,6,4,1,0,2,0xaa,0xbb},request[12]={13,0,0,8,1,1,0,2,4,1,0,0};net_tls_server_key_exchange_view_t exchange_view;net_tls_certificate_request_view_t request_view;TEST_ASSERT_EQUAL(0,net_tls_server_key_exchange_parse(exchange,sizeof(exchange),&exchange_view));TEST_ASSERT_EQUAL(23,exchange_view.named_curve);TEST_ASSERT_EQUAL(3,exchange_view.public_key_length);TEST_ASSERT_EQUAL(4,exchange_view.public_key[0]);TEST_ASSERT_EQUAL(2,exchange_view.signature_length);TEST_ASSERT_EQUAL(0,net_tls_certificate_request_parse(request,sizeof(request),&request_view));TEST_ASSERT_EQUAL(1,request_view.certificate_types_length);TEST_ASSERT_EQUAL(2,request_view.signature_algorithms_length);TEST_ASSERT_EQUAL(0,request_view.certificate_authorities_length);exchange[7]=0;TEST_ASSERT_NOT_EQUAL(0,net_tls_server_key_exchange_parse(exchange,sizeof(exchange),&exchange_view));request[6]=3;TEST_ASSERT_NOT_EQUAL(0,net_tls_certificate_request_parse(request,sizeof(request),&request_view));}
void test_tls_server_message_dispatch(void){uint8_t hello[42]={0},certificate[13]={11,0,0,9,0,0,6,0,0,3,'X','Y','Z'},exchange[17]={12,0,0,13,3,0,23,3,4,5,6,4,1,0,2,0xaa,0xbb},request[12]={13,0,0,8,1,1,0,2,4,1,0,0},done[4]={14,0,0,0},transcript_buffer[96]={0};net_tls_handshake_t handshake;net_tls_transcript_t transcript;hello[0]=2;hello[3]=38;hello[4]=3;hello[5]=3;hello[38]=0;hello[39]=0;hello[40]=0x9c;hello[41]=0;TEST_ASSERT_EQUAL(0,net_tls_handshake_init(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_client_hello(&handshake));TEST_ASSERT_EQUAL(0,net_tls_transcript_init(&transcript,transcript_buffer,sizeof(transcript_buffer)));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_message(&handshake,hello,sizeof(hello),&transcript));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_message(&handshake,certificate,sizeof(certificate),&transcript));TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_message(&handshake,exchange,sizeof(exchange),&transcript));TEST_ASSERT_EQUAL(23,handshake.server_named_curve);TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_message(&handshake,request,sizeof(request),&transcript));TEST_ASSERT_EQUAL(1,handshake.certificate_requested);TEST_ASSERT_EQUAL(0,net_tls_handshake_accept_server_message(&handshake,done,sizeof(done),&transcript));TEST_ASSERT_EQUAL(NET_TLS_HANDSHAKE_SERVER_HELLO_DONE_RECEIVED,handshake.state);TEST_ASSERT_EQUAL(88,transcript.length);TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_accept_server_message(&handshake,done,sizeof(done),&transcript));}
void test_tls_client_flight_build_and_state(void){uint8_t certificate[8]={0},exchange[16]={0},record[32]={0},public_key[3]={4,5,6},verify[12]={0},i;net_tls_record_view_t view;net_tls_handshake_t handshake;for(i=0;i<12;i++)verify[i]=i;TEST_ASSERT_EQUAL(7,net_tls_client_certificate_empty_build(certificate,sizeof(certificate)));TEST_ASSERT_EQUAL(11,certificate[0]);TEST_ASSERT_EQUAL(0,certificate[6]);TEST_ASSERT_EQUAL(8,net_tls_client_key_exchange_build(exchange,sizeof(exchange),public_key,sizeof(public_key)));TEST_ASSERT_EQUAL(16,exchange[0]);TEST_ASSERT_EQUAL(4,exchange[5]);TEST_ASSERT_EQUAL(6,exchange[7]);TEST_ASSERT_EQUAL(6,net_tls_change_cipher_spec_build(record,sizeof(record)));TEST_ASSERT_EQUAL(0,net_tls_record_parse(record,6,&view));TEST_ASSERT_EQUAL(NET_TLS_CONTENT_CHANGE_CIPHER_SPEC,view.content_type);TEST_ASSERT_EQUAL(1,view.payload[0]);TEST_ASSERT_EQUAL(21,net_tls_finished_build(record,sizeof(record),verify));TEST_ASSERT_EQUAL(0,net_tls_record_parse(record,21,&view));TEST_ASSERT_EQUAL(16,view.payload_length);TEST_ASSERT_EQUAL(20,view.payload[0]);TEST_ASSERT_EQUAL(11,view.payload[15]);TEST_ASSERT_EQUAL(0,net_tls_handshake_init(&handshake));handshake.state=NET_TLS_HANDSHAKE_SERVER_HELLO_DONE_RECEIVED;handshake.certificate_requested=1;TEST_ASSERT_EQUAL(0,net_tls_handshake_note_client_certificate(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_client_key_exchange(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_change_cipher_spec(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_finished(&handshake));TEST_ASSERT_EQUAL(NET_TLS_HANDSHAKE_FINISHED_SENT,handshake.state);TEST_ASSERT_EQUAL(0,net_tls_handshake_init(&handshake));handshake.state=NET_TLS_HANDSHAKE_SERVER_HELLO_DONE_RECEIVED;TEST_ASSERT_NOT_EQUAL(0,net_tls_handshake_note_client_certificate(&handshake));TEST_ASSERT_EQUAL(0,net_tls_handshake_note_client_key_exchange(&handshake));}
void test_tls_accumulator_fragments(void){uint8_t record[16]={0},buffer[16]={0},payload[3]={'X','Y','Z'};uint8_t fragment[8];net_tls_record_accumulator_t accumulator;net_tls_record_view_t view;TEST_ASSERT_EQUAL(8,net_tls_record_build(record,sizeof(record),NET_TLS_CONTENT_HANDSHAKE,payload,3));for(uint8_t i=0;i<4;i++)fragment[i]=record[i];TEST_ASSERT_EQUAL(0,net_tls_record_accumulator_init(&accumulator,buffer,sizeof(buffer)));TEST_ASSERT_EQUAL(1,net_tls_record_accumulator_feed(&accumulator,fragment,4,&view));TEST_ASSERT_EQUAL(4,accumulator.length);TEST_ASSERT_EQUAL(0,net_tls_record_accumulator_feed(&accumulator,record+4,4,&view));TEST_ASSERT_EQUAL(8,accumulator.length);TEST_ASSERT_EQUAL(3,view.payload_length);TEST_ASSERT_EQUAL('Z',view.payload[2]);}
void test_tls_client_hello_build(void){uint8_t record[64]={0},random[32]={0},i;net_tls_record_view_t view;for(i=0;i<32;i++)random[i]=i;TEST_ASSERT_EQUAL(50,net_tls_client_hello_build(record,sizeof(record),random));TEST_ASSERT_EQUAL(0,net_tls_record_parse(record,50,&view));TEST_ASSERT_EQUAL(NET_TLS_CONTENT_HANDSHAKE,view.content_type);TEST_ASSERT_EQUAL(45,view.payload_length);TEST_ASSERT_EQUAL(1,view.payload[0]);TEST_ASSERT_EQUAL(44,view.payload[3]);TEST_ASSERT_EQUAL(0,view.payload[38]);TEST_ASSERT_EQUAL(0,view.payload[39]);TEST_ASSERT_NOT_EQUAL(0,net_tls_client_hello_build(record,49,random));}
void test_tls_record_parse_stream_bounds(void){uint8_t record[16]={0},payload[3]={'A','B','C'};uint16_t consumed=99;net_tls_record_view_t view;TEST_ASSERT_EQUAL(8,net_tls_record_build(record,sizeof(record),NET_TLS_CONTENT_HANDSHAKE,payload,3));TEST_ASSERT_NOT_EQUAL(0,net_tls_record_parse_stream(record,4,&view,&consumed));TEST_ASSERT_EQUAL(0,consumed);TEST_ASSERT_EQUAL(0,net_tls_record_parse_stream(record,8,&view,&consumed));TEST_ASSERT_EQUAL(8,consumed);TEST_ASSERT_EQUAL(3,view.payload_length);TEST_ASSERT_NOT_EQUAL(0,net_tls_record_parse_stream(record,7,&view,&consumed));}
void test_tls_record_build_parse(void){uint8_t record[32]={0},payload[3]={'C','H','1'};net_tls_record_view_t view;TEST_ASSERT_EQUAL(8,net_tls_record_build(record,sizeof(record),NET_TLS_CONTENT_HANDSHAKE,payload,3));TEST_ASSERT_EQUAL(0,net_tls_record_parse(record,8,&view));TEST_ASSERT_EQUAL(NET_TLS_CONTENT_HANDSHAKE,view.content_type);TEST_ASSERT_EQUAL(3,view.payload_length);TEST_ASSERT_EQUAL('C',view.payload[0]);record[2]=2;TEST_ASSERT_NOT_EQUAL(0,net_tls_record_parse(record,8,&view));}
int main(void){unity_init();RUN_TEST(test_tls_handshake_state);RUN_TEST(test_tls_server_hello_parse);RUN_TEST(test_tls_certificate_parse);RUN_TEST(test_tls_certificate_handshake_state);RUN_TEST(test_tls_server_hello_done);RUN_TEST(test_tls_server_hello_done_state);RUN_TEST(test_tls_handshake_fragment_and_transcript);RUN_TEST(test_tls_server_key_exchange_and_certificate_request);RUN_TEST(test_tls_server_message_dispatch);RUN_TEST(test_tls_client_flight_build_and_state);RUN_TEST(test_tls_accumulator_fragments);RUN_TEST(test_tls_record_parse_stream_bounds);RUN_TEST(test_tls_client_hello_build);RUN_TEST(test_tls_record_build_parse);unity_print_results();unity_cleanup();return unity_stats.tests_failed==0?0:1;}
